begin;
insert into auth.users(id,email,email_confirmed_at) values('10000000-0000-4000-8000-000000000021','payments@softhaven.invalid',now()),('10000000-0000-4000-8000-000000000022','other@softhaven.invalid',now());
insert into public.shipping_zones(id,name) values('20000000-0000-4000-8000-000000000021','Payment test');
insert into public.shipping_rates(id,zone_id,name,rate) values('20000000-0000-4000-8000-000000000022','20000000-0000-4000-8000-000000000021','Payment test',200);
update public.site_settings set value='{"bank_name":"Test bank","account_name":"Fixture account","account_number":"123456","branch":"Fixture branch","instructions":"Fixture only","enabled":true}' where id='bank_transfer';
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
select public.adjust_inventory((select id from public.product_variants where product_id='aurelius' limit 1),30,'stock received');
do $$ declare customer uuid:='10000000-0000-4000-8000-000000000021';v uuid;lines jsonb;addr jsonb:='{"name":"Test Customer","phone":"0771234567","address":"Test road","city":"Colombo","district":"Colombo","country":"LK"}';a jsonb;b jsonb;c jsonb;attempt uuid;receipt uuid;replacement uuid;before_stock integer;after_stock integer;begin
 select id,stock into v,before_stock from public.product_variants where product_id='aurelius' limit 1;
 lines:=jsonb_build_array(jsonb_build_object('variant_id',v,'quantity',1));
 if has_function_privilege('authenticated','public.create_payment_order(uuid,text,jsonb,jsonb,uuid,uuid,uuid,text,integer,text,text)','EXECUTE') then raise exception 'Order commit exposed directly';end if;
 if has_function_privilege('authenticated','private.commerce_checkout(jsonb,jsonb,uuid,text,integer,boolean,uuid,text)','EXECUTE') then raise exception 'Legacy private commit exposed';end if;
 a:=public.create_payment_order(customer,'card',lines,addr,'20000000-0000-4000-8000-000000000022','40000000-0000-4000-8000-000000000021');attempt:=(a->>'attempt_id')::uuid;
 b:=public.create_payment_order(customer,'card',lines,addr,'20000000-0000-4000-8000-000000000022','40000000-0000-4000-8000-000000000021');
 if a->>'id'<>b->>'id' then raise exception 'Duplicate order';end if;
 begin perform public.record_payhere_notification(attempt,'pay-1',999,'LKR',2);raise exception 'Wrong amount accepted';exception when others then if sqlerrm<>'Payment notification mismatch' then raise;end if;end;
 begin perform public.record_payhere_notification(attempt,'pay-1',(a->>'amount')::numeric,'USD',2);raise exception 'Wrong currency accepted';exception when others then if sqlerrm<>'Payment notification mismatch' then raise;end if;end;
 perform public.record_payhere_notification(attempt,'pay-1',(a->>'amount')::numeric,'LKR',0);
 if (select payment_status from public.orders where id=(a->>'id')::uuid)<>'pending' then raise exception 'Pending marked paid';end if;
 perform public.record_payhere_notification(attempt,'pay-1',(a->>'amount')::numeric,'LKR',2);
 perform public.record_payhere_notification(attempt,'pay-1',(a->>'amount')::numeric,'LKR',2);
 perform public.record_payhere_notification(attempt,'pay-1',(a->>'amount')::numeric,'LKR',-2);
 if (select payment_status from public.orders where id=(a->>'id')::uuid)<>'paid' then raise exception 'Paid downgraded by failure';end if;
 select stock into after_stock from public.product_variants where id=v;if after_stock<>before_stock-1 then raise exception 'Duplicate stock deduction';end if;
 perform public.record_payhere_notification(attempt,'pay-1',(a->>'amount')::numeric,'LKR',-3);
 if not (select payment_review_required from public.orders where id=(a->>'id')::uuid) then raise exception 'Chargeback not flagged';end if;
 perform public.record_payhere_notification(attempt,'pay-1',(a->>'amount')::numeric,'LKR',2);
 if (select payment_status from public.orders where id=(a->>'id')::uuid)='paid' then raise exception 'Chargeback incorrectly reversed';end if;
 begin perform public.create_payment_order(customer,'bank_transfer',lines,addr,'20000000-0000-4000-8000-000000000022',gen_random_uuid(),p_bank_version=>md5((select value::text from public.site_settings where id='bank_transfer')));raise exception 'Missing receipt accepted';exception when others then if sqlerrm<>'A valid owned receipt is required' then raise;end if;end;
 insert into storage.objects(bucket_id,name) values('payment-receipts',customer::text||'/first.webp');receipt:=public.register_payment_receipt(customer,customer::text||'/first.webp',1000);
 begin perform public.create_payment_order('10000000-0000-4000-8000-000000000022','bank_transfer',lines,addr,'20000000-0000-4000-8000-000000000022',gen_random_uuid(),receipt,p_bank_version=>md5((select value::text from public.site_settings where id='bank_transfer')));raise exception 'Foreign receipt accepted';exception when others then if sqlerrm<>'A valid owned receipt is required' then raise;end if;end;
 begin perform public.create_payment_order(customer,'bank_transfer',lines,addr,'20000000-0000-4000-8000-000000000022',gen_random_uuid(),receipt,p_bank_version=>'00000000000000000000000000000000');raise exception 'Stale bank details accepted';exception when others then if sqlerrm<>'Bank details changed; refresh checkout' then raise;end if;end;
 b:=public.create_payment_order(customer,'bank_transfer',lines,addr,'20000000-0000-4000-8000-000000000022','40000000-0000-4000-8000-000000000022',receipt,p_bank_version=>md5((select value::text from public.site_settings where id='bank_transfer')));
 if b->>'payment_status'<>'pending' then raise exception 'Bank marked paid automatically';end if;
 perform set_config('request.jwt.claim.sub',customer::text,true);
 begin perform public.verify_bank_payment((b->>'id')::uuid,true,'Spoof approval');raise exception 'Customer approved payment';exception when others then if sqlerrm<>'Permission denied' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',true);
 begin perform public.update_order((b->>'id')::uuid,'confirmed');raise exception 'Unpaid fulfilment accepted';exception when others then if sqlerrm<>'Verified payment is required before fulfilment' then raise;end if;end;
 perform public.verify_bank_payment((b->>'id')::uuid,false,'Receipt unclear');
 insert into storage.objects(bucket_id,name) values('payment-receipts',customer::text||'/second.webp');replacement:=public.register_payment_receipt(customer,customer::text||'/second.webp',1000);
 perform public.resubmit_bank_receipt(customer,(b->>'id')::uuid,replacement);
 perform public.verify_bank_payment((b->>'id')::uuid,true,'Verified transfer');
 begin perform public.verify_bank_payment((b->>'id')::uuid,true,'Repeated approval');raise exception 'Approval repeated';exception when others then if sqlerrm<>'Payment verification unavailable' then raise;end if;end;
 select stock into after_stock from public.product_variants where id=v;if after_stock<>before_stock-2 then raise exception 'Bank approval deducted stock twice';end if;
 c:=public.create_payment_order(customer,'card',lines,addr,'20000000-0000-4000-8000-000000000022','40000000-0000-4000-8000-000000000023');
 perform public.record_payhere_notification((c->>'attempt_id')::uuid,'pay-retry',(c->>'amount')::numeric,'LKR',-2);
 attempt:=(c->>'attempt_id')::uuid;
 c:=public.retry_payhere_payment(customer,(c->>'id')::uuid,'40000000-0000-4000-8000-000000000024');
 if (c->>'attempt_id')::uuid=attempt then raise exception 'Retry reused consumed attempt';end if;
 update private.payment_reservations set expires_at=now()-interval '1 minute' where order_id=(c->>'id')::uuid;
 perform public.expire_payment_reservations();perform public.expire_payment_reservations();
 select stock into after_stock from public.product_variants where id=v;if after_stock<>before_stock-2 then raise exception 'Reservation release incorrect';end if;
 perform public.record_payhere_notification((c->>'attempt_id')::uuid,'pay-late',(c->>'amount')::numeric,'LKR',2);
 if not (select payment_review_required and status='cancelled' and payment_status='paid' from public.orders where id=(c->>'id')::uuid) then raise exception 'Late payment incorrectly fulfilled';end if;
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000022',true);
 begin perform public.payment_receipt_access(receipt);raise exception 'Foreign receipt readable';exception when others then if sqlerrm<>'Permission denied' then raise;end if;end;
end $$;
